veringen.\",\"_cards_2_card_text\":\"field_7e8f0a1b2c3d9\",\"cards_3_card_title\":\"4. Lancering en vieren\",\"_cards_3_card_title\":\"field_7e8f0a1b2c3d8\",\"cards_3_card_text\":\"Een feedbackronde is verwerkt en alles is uitgebreid getest. We gaan live! Na de lancering blijft TechnoSapiens uiteraard in beeld voor optimalisatie en support. Zullen we dit succes samen vieren?\",\"_cards_3_card_text\":\"field_7e8f0a1b2c3d9\",\"cards\":4,\"_cards\":\"field_7e8f0a1b2c3d7\",\"call_to_action\":{\"title\":\"Zullen we kennismaken?\",\"url\":\"https://technosapiens.test/contact/\",\"target\":\"\"},\"_call_to_action\":\"field_7e8f0a1b2c3da\",\"section_margin_top\":\"mt-xl\",\"_section_margin_top\":\"field_6a4a4ab0b6dc0\",\"section_margin_bottom\":\"mb-xl\",\"_section_margin_bottom\":\"field_6156ab4c687e8\",\"section_vignet_top\":\"1\",\"_section_vignet_top\":\"field_6aaeef9d735d6\",\"section_vignet_bottom\":\"1\",\"_section_vignet_bottom\":\"field_6aaeefd2735d7\",\"background_type\":\"bands\",\"_background_type\":\"field_6aaef7702bdba\",\"background_bands_axis\":\"vertical\",\"_background_bands_axis\":\"field_6aaef7c42bdbb\",\"background_bands_size\":\"xlarge\",\"_background_bands_size\":\"field_6aaef84e3c58f\",\"background_bands_anim_dir\":\"center\",\"_background_bands_anim_dir\":\"field_6aaef8153c58e\"}} /-->\n\n<!-- wp:acf/section-section-brands {\"name\":\"acf/section-section-brands\",\"data\":{\"section_title\":\"Staat \\u003cspan class=\\u0022text-color-tertiary\\u0022\\u003ejouw logo\\u003c/span\\u003e hier straks ook bij?\",\"_section_title\":\"field_6d9e0f1a2b3c5\",\"title_heading_tag\":\"h2\",\"_title_heading_tag\":\"field_6d9e0f1a2b3c6\",\"brands_0_brand_logo\":244,\"_brands_0_brand_logo\":\"field_6d9e0f1a2b3c8\",\"brands_0_brand_link\":\"\",\"_brands_0_brand_link\":\"field_6d9e0f1a2b3c9\",\"brands_1_brand_logo\":273,\"_brands_1_brand_logo\":\"field_6d9e0f1a2b3c8\",\"brands_1_brand_link\":\"\",\"_brands_1_brand_link\":\"field_6d9e0f1a2b3c9\",\"brands_2_brand_logo\